"use strict";

var skip = false

// Recieves a list of entities to replace the current selection
function Selection_New(msg)
{
    var entities = msg.entities
    //$.Msg("Selection_New ", entities)
    for (var i in entities) {
        if (i==1)
            GameUI.SelectUnit(entities[i], false) //New
        else
            GameUI.SelectUnit(entities[i], true) //Add
    };
    $.Schedule(0.03, SendSelectedEntities);
}

// Recieves a list of entities to add to the current selection
function Selection_Add(msg)
{
    var entities = msg.entities
    //$.Msg("Selection_Add ", entities)
    for (var i in entities) {
        GameUI.SelectUnit(entities[i], true)
    };
    $.Schedule(0.03, SendSelectedEntities);
}

// Removes a list of entities from the current selection
function Selection_Remove(msg)
{
    var remove_entities = msg.entities
    //$.Msg("Selection_Remove ", remove_entities)
    var selected_entities = GetSelectedEntities();
    for (var i in remove_entities) {
        var index = selected_entities.indexOf(remove_entities[i])
        if (index > -1)
            selected_entities.splice(index, 1)
    };

    if (selected_entities.length == 0)
    {
        Selection_Reset()
        return
    }

    for (var i in selected_entities) {
        if (i==0)
            GameUI.SelectUnit(selected_entities[i], false) //New
        else
            GameUI.SelectUnit(selected_entities[i], true) //Add
    };
    $.Schedule(0.03, SendSelectedEntities);
}

// Fall back to the default selection
function Selection_Reset(msg)
{
    var playerID = Players.GetLocalPlayer()
    var heroIndex = Players.GetPlayerHeroEntityIndex(playerID)
    GameUI.SelectUnit(heroIndex, false)
    $.Schedule(0.03, SendSelectedEntities);
}

// Filter & Sending
function OnUpdateSelectedUnit()
{
    //$.Msg( "OnUpdateSelectedUnit ", Players.GetLocalPlayerPortraitUnit() );
    if (skip == true){
        skip = false;
        return
    }
    var cfg = GameUI.CustomUIConfig();
    if (cfg) {
        cfg.selection_is_position = (Players.GetLocalPlayerPortraitUnit() === -1);
    }

    // Skips units from the selected group
    SelectionFilter(GetSelectedEntities())

    $.Schedule(0.03, SendSelectedEntities);
}

// Updates the list of selected entities on server for this player
function SendSelectedEntities() {
    GameEvents.SendCustomGameEventToServer("selection_update", {entities: GetSelectedEntities()})
}

// Local player shortcut
function GetSelectedEntities() {
    return Players.GetSelectedEntities(Players.GetLocalPlayer());
}

// Returns an index of an override defined on lua with npcHandle:SetSelectionOverride(reselect_unit)
function GetSelectionOverride(entityIndex) {
    var table = CustomNetTables.GetTableValue("selection", entityIndex)
    return table ? table.entity : -1
}

function OnUpdateQueryUnit()
{
    //$.Msg( "OnUpdateQueryUnit ", Players.GetQueryUnit(Players.GetLocalPlayer()));
}

(function () {
    // Custom event listeners
    GameEvents.Subscribe("selection_new", Selection_New);
    GameEvents.Subscribe("selection_add", Selection_Add);
    GameEvents.Subscribe("selection_remove", Selection_Remove);
    GameEvents.Subscribe("selection_reset", Selection_Reset);

    // Built-In Dota client events
    GameEvents.Subscribe("dota_player_update_selected_unit", OnUpdateSelectedUnit);
    GameEvents.Subscribe("dota_player_update_query_unit", OnUpdateQueryUnit);

    function UpdateShop1DummyRange(event) {
        var cfg = GameUI.CustomUIConfig();
        if (!cfg) {
            return;
        }

        var ent = event && event.entindex !== undefined ? event.entindex : -1;
        var proxyEnt = event && event.selection_proxy_entindex !== undefined ? event.selection_proxy_entindex : -1;
        var ability = event && event.ability ? event.ability : "";
        var range = event && event.projectile_range !== undefined ? Number(event.projectile_range) : 0;
        if (!ability || ent === -1 || !isFinite(range) || range <= 0) {
            cfg.shop1_dummy_ent = -1;
            cfg.shop1_dummy_proxy_ent = -1;
            cfg.shop1_dummy_range = 0;
            return;
        }

        cfg.shop1_dummy_ent = ent;
        cfg.shop1_dummy_proxy_ent = proxyEnt;
        cfg.shop1_dummy_range = range;
    }

    GameEvents.Subscribe("shop1_dummy_selection", UpdateShop1DummyRange);
    GameEvents.Subscribe("shop1_dummy_refresh", UpdateShop1DummyRange);
})();

// Shop1 mouse handling (moved from init.js)
(function () {
    var shop1MouseCallbackReady = false;
    var lastCameraWheelTime = 0;
    var cameraWheelCooldown = 0.03;

    function SendCameraWheel(delta) {
        if (!delta || delta === 0) {
            return false;
        }
        var now = Game.GetGameTime();
        if (now - lastCameraWheelTime < cameraWheelCooldown) {
            return true;
        }
        lastCameraWheelTime = now;
        GameEvents.SendCustomGameEventToServer("camera_zoom_override", { delta: delta });
        return true;
    }

    function RegisterShop1MouseCallback(force) {
        if (shop1MouseCallbackReady && !force) {
            return;
        }
        if (!GameUI || !GameUI.SetMouseCallback) {
            return;
        }

        GameUI.SetMouseCallback(function (eventName, arg) {
            if (eventName === "wheeled") {
                var delta = 0;
                if (typeof arg === "number") {
                    delta = arg;
                } else if (arg === "MOUSE_WHEEL_UP") {
                    delta = 1;
                } else if (arg === "MOUSE_WHEEL_DOWN") {
                    delta = -1;
                }
                return SendCameraWheel(delta);
            }
            if (eventName !== "pressed") {
                return false;
            }
            if (arg !== "MOUSE_LEFT" && arg !== 0) {
                return false;
            }

            var now = Game.GetGameTime();
            var cfg = GameUI.CustomUIConfig();
            if (cfg) {
                cfg.last_left_click_time = now;
            }

            var pid = Players.GetLocalPlayer();
            var cursor = GameUI.GetCursorPosition();
            if (cursor && cursor.length >= 2) {
                var clickedTarget = false;
                if (GameUI.FindScreenEntities) {
                    var ents = GameUI.FindScreenEntities(cursor[0], cursor[1]);
                    if (ents && ents.length > 0) {
                        for (var i = 0; i < ents.length; i++) {
                            var e = ents[i];
                            if (e && e.entityIndex && e.entityIndex !== -1) {
                                if (Entities.IsHero && Entities.IsHero(e.entityIndex)) {
                                    clickedTarget = true;
                                    break;
                                }
                                var name = Entities.GetUnitName(e.entityIndex) || "";
                                if (name.indexOf("npc_dota_auto_cast_dummy") === 0) {
                                    clickedTarget = true;
                                    break;
                                }
                            }
                        }
                    }
                }
                if (cfg) {
                    cfg.selection_force_close = !clickedTarget;
                    cfg.selection_force_close_time = now;
                }

                var world = GameUI.GetScreenWorldPosition(cursor[0], cursor[1]);
                if (world) {
                    if (cfg) {
                        cfg.shop1_click_select_time = now;
                    }
                    GameEvents.SendCustomGameEventToServer("shop1_click_select", {
                        x: world[0],
                        y: world[1],
                        z: world[2]
                    });
                }
            }

            var selected = Players.GetSelectedEntities(pid);
            if (!selected || selected.length < 1) {
                return false;
            }

            var ent = selected[0];
            if (!ent || ent < 0) {
                return false;
            }

            var unitName = Entities.GetUnitName(ent) || "";
            if (unitName.indexOf("npc_dota_auto_cast_dummy") !== 0) {
                return false;
            }

            if (!cursor || cursor.length < 2) {
                return false;
            }

            if (GameUI.FindScreenEntities) {
                var ents = GameUI.FindScreenEntities(cursor[0], cursor[1]);
                if (ents && ents.length > 0) {
                    for (var i = 0; i < ents.length; i++) {
                        var e = ents[i];
                        if (e && e.entityIndex && e.entityIndex !== -1) {
                            return false;
                        }
                    }
                }
            }

            var world = GameUI.GetScreenWorldPosition(cursor[0], cursor[1]);
            if (!world) {
                return false;
            }

            Game.PrepareUnitOrders({
                OrderType: dotaunitorder_t.DOTA_UNIT_ORDER_MOVE_TO_POSITION,
                UnitIndex: ent,
                Position: world,
                Queue: false
            });

            return true;
        });

        shop1MouseCallbackReady = true;
    }

    RegisterShop1MouseCallback();
    GameEvents.Subscribe("shop1_mouse_bind", function () {
        RegisterShop1MouseCallback(true);
    });
})();

