{
  GameUI.SetCameraPitchMax( 90 );
  GameUI.SetCameraPitchMin( 90 );
  GameUI.SetCameraYaw( 0 );
}

function SideXCamera()
{
  GameUI.SetCameraPitchMax( 1 );
  GameUI.SetCameraPitchMin( 1 );
