function MouseCalc(panel, dif, scale)
{
  var num = parseFloat(panel.text);
  if(isNaN(num)) {
    panel.text = num.toString();
    num = 0;
  }
  var angle = num + (scale * dif);
  angle = Math.round(angle * 100) / 100;
  return angle.toString();
}

