        var sx_dy = Game.WorldToScreenX(guess[0], guess[1] + step, guess[2]);
        var sy_dy = Game.WorldToScreenY(guess[0], guess[1] + step, guess[2]);
        var a = (sx_dx - sx) / step;
        var b = (sx_dy - sx) / step;
        var c = (sy_dx - sy) / step;
        var d = (sy_dy - sy) / step;
        var det = a * d - b * c;
        if (!isFinite(det) || Math.abs(det) < 1e-6) {
            break;
        }
        var invA = d / det;
        var invB = -b / det;
        var invC = -c / det;
        var invD = a / det;
        var deltaX = invA * dx + invB * dy;
        var deltaY = invC * dx + invD * dy;
        guess[0] += deltaX;
        guess[1] += deltaY;
    }
    return guess;
}

function StopShop1DragFx() {
    if (!shop1DragFx.active) {
        return;
    }
    shop1DragFx.active = false;
    if (shop1DragFx.iconPanel) {
        shop1DragFx.iconPanel.visible = false;
    }
    if (GameEvents) {
        GameEvents.SendCustomGameEventToServer("shop1_drag_fx_stop", {});
    }
}

function StartShop1DragFx(sourceEnt, iconPath) {
    if (!sourceEnt || sourceEnt < 0 || !iconPath) {
        return;
    }
    if (shop1DragFx.active && shop1DragFx.sourceEnt === sourceEnt && shop1DragFx.iconPath === iconPath) {
        return;
    }
    StopShop1DragFx();
    shop1DragFx.active = true;
    shop1DragFx.sourceEnt = sourceEnt;
    shop1DragFx.iconPath = iconPath;
    if (!shop1DragFx.container) {
        shop1DragFx.container = $("#Shop1DragLayer");
        if (!shop1DragFx.container) {
            var parent = GetHudPanelSafe();
            shop1DragFx.hud = parent;
            shop1DragFx.container = $.CreatePanel("Panel", parent, "Shop1DragLayer");
            shop1DragFx.container.style.width = "100%";
            shop1DragFx.container.style.height = "100%";
            shop1DragFx.container.style.flowChildren = "none";
            shop1DragFx.container.style.zIndex = "1000";
            shop1DragFx.container.hittest = false;
        }
    } else if (!shop1DragFx.hud && typeof GetDotaHud === "function") {
        shop1DragFx.hud = GetHudPanelSafe();
    }
    // icon display moved to world panel, particle handled on server
    if (GameEvents) {
        var cursorPos = GameUI.GetCursorPosition();
        if (cursorPos && cursorPos.length >= 2) {
            var world = ScreenToWorldAtZ(cursorPos[0], cursorPos[1], 1000);
            if (world) {
                GameEvents.SendCustomGameEventToServer("shop1_drag_fx_start", {
                    x: world[0],
                    y: world[1],
                    z: world[2],
                    icon: iconPath,
                    source_ent: sourceEnt
                });
            }
        }
    }
    UpdateShop1DragFx();
}

function UpdateShop1DragFxState() {
    if (!shop1DragFx.active) {
        return;
    }
    if (!shop1LeftDown) {
        StopShop1DragFx();
        return;
    }
    var selected = Players.GetSelectedEntities(Players.GetLocalPlayer());
    var ent = selected && selected.length > 0 ? selected[0] : -1;
    var sourceEnt = GetShop1DragSourceEnt();
    if (!ent || ent < 0 || !sourceEnt || sourceEnt < 0) {
        StopShop1DragFx();
        return;
    }
    var cfg = GameUI.CustomUIConfig();
    var proxyEnt = cfg && cfg.shop1_dummy_proxy_ent !== undefined ? cfg.shop1_dummy_proxy_ent : -1;
    if (ent !== sourceEnt && ent !== proxyEnt) {
        StopShop1DragFx();
        return;
    }
    var heroIcon = GetShop1HeroIcon();
    if (!heroIcon) {
        StopShop1DragFx();
        return;
    }
}

function UpdateShop1DragFx() {
    if (!shop1DragFx.active) {
        return;
    }
    var cursor = GameUI.GetCursorPosition();
    if (cursor && cursor.length >= 2) {
        var world = ScreenToWorldAtZ(cursor[0], cursor[1], 500);
        if (world && GameEvents) {
            GameEvents.SendCustomGameEventToServer("shop1_drag_fx_update", {
                x: world[0],
                y: world[1],
                z: world[2]
            });
        }
    }
    $.Schedule(0.03, UpdateShop1DragFx);
}

