    function UpdateShop1DummyRange(event) {
        var cfg = GameUI.CustomUIConfig();
        if (!cfg) {
            return;
        }

        var ent = event && event.entindex !== undefined ? event.entindex : -1;
        var proxyEnt = event && event.selection_proxy_entindex !== undefined ? event.selection_proxy_entindex : -1;
        var ability = event && event.ability ? event.ability : "";
        var range = event && event.projectile_range !== undefined ? Number(event.projectile_range) : 0;

        var heroIcon = event && event.hero_icon ? event.hero_icon : "";
        if (!ability || ent === -1) {
            cfg.shop1_dummy_ent = -1;
            cfg.shop1_dummy_proxy_ent = -1;
            cfg.shop1_dummy_range = 0;
            cfg.shop1_dummy_hero_icon = "";
            StopShop1DragFx();
            return;
        }

        cfg.shop1_dummy_ent = ent;
        cfg.shop1_dummy_proxy_ent = proxyEnt;
        if (!isFinite(range) || range < 0) {
            range = 0;
        }
        cfg.shop1_dummy_range = range;
        cfg.shop1_dummy_hero_icon = heroIcon || "";
    }

    GameEvents.Subscribe("shop1_dummy_selection", UpdateShop1DummyRange);
    GameEvents.Subscribe("shop1_dummy_refresh", UpdateShop1DummyRange);
})();

